1	// KOL / Agency partner commission engine.
2	//
3	// The peer-referral program (lib/actions-growth.ts maybeRewardReferral +
4	// User.referralCode/referredById + AffiliatePayout) pays a customer a ONE-TIME
5	// wallet bonus for referring a friend. THIS module is a separate, additive
6	// program for agencies / content creators (KOLs): a partner is permanently
7	// attached to a customer they brought on (PartnerCustomer) and earns a LIFETIME
8	// percentage on EVERY qualifying charge that customer makes — the initial order
9	// AND every renewal, across all products — recorded as a PartnerCommission row.
10	//
11	// Idempotency: PartnerCommission.invoiceId is UNIQUE, so at most one commission
12	// row can ever exist per charge. Every accrual path (the inline hooks after an
13	// order/renewal, and the background reconciliation sweep) funnels through
14	// `accrueCommissionForInvoice`, which swallows the unique-violation on a
15	// re-attempt. A partner therefore can never be double-accrued for one charge.
16	
17	import { db } from "./db";
18	import type { Invoice, Prisma } from "@prisma/client";
19	
20	/**
21	 * Invoice descriptions that are NOT service sales and must never earn commission:
22	 *  - wallet top-ups (money IN, not a purchase — the service it later funds is its
23	 *    own invoice and is what earns the commission; accruing on both would double
24	 *    count). "Wallet top-up" is lib/stripe.ts; "Automatic wallet top-up" is the
25	 *    auto-recharge in worker/billing.ts (AUTO_RECHARGE_DESC).
26	 * Refunds/credits are excluded separately by the `amountCents <= 0` guard below.
27	 */
28	const NON_COMMISSIONABLE_DESCRIPTIONS = new Set(["Wallet top-up", "Automatic wallet top-up"]);
29	
30	export type CommissionableInvoice = Pick<
31	  Invoice,
32	  "id" | "userId" | "status" | "amountCents" | "taxCents" | "description" | "createdAt"
33	>;
34	
35	/**
36	 * Is this invoice a qualifying charge a partner earns commission on? True for any
37	 * PAID invoice with a positive total that isn't a wallet top-up. This is the one
38	 * classifier every accrual path shares.
39	 */
40	export function isCommissionableInvoice(inv: CommissionableInvoice): boolean {
41	  if (inv.status !== "PAID") return false;
42	  if (inv.amountCents <= 0) return false; // refunds / zero-value docs
43	  if (NON_COMMISSIONABLE_DESCRIPTIONS.has(inv.description.trim())) return false;
44	  return true;
45	}
46	
47	/** Coarse kind label for the ledger, inferred from the invoice description. */
48	function inferKind(description: string): "ORDER" | "RENEWAL" | "CHARGE" {
49	  const d = description.toLowerCase();
50	  if (d.includes("renewal") || d.startsWith("renew")) return "RENEWAL";
51	  if (d.startsWith("order:")) return "ORDER";
52	  return "CHARGE";
53	}
54	
55	/**
56	 * Accrue the partner commission for a single qualifying invoice, IF the invoice's
57	 * owner is attached to an ACTIVE partner and no commission has been recorded yet.
58	 *
59	 * Idempotent and safe to call from anywhere, any number of times:
60	 *  - not commissionable / no partner attachment / paused partner  -> returns null.
61	 *  - a commission already exists for the invoice (unique invoiceId) -> returns null
62	 *    (the create throws P2002, which is swallowed).
63	 * Commission is computed on the NET (pre-tax) charge = amountCents - taxCents.
64	 *
65	 * Never throws for the "expected" cases; unexpected DB errors DO propagate so the
66	 * caller (which wraps this best-effort) can log them.
67	 */
68	export async function accrueCommissionForInvoice(
69	  inv: CommissionableInvoice
70	): Promise<{ commissionId: string; amountCents: number } | null> {
71	  if (!isCommissionableInvoice(inv)) return null;
72	
73	  const attachment = await db.partnerCustomer.findUnique({
74	    where: { customerId: inv.userId },
75	    include: { partner: true },
76	  });
77	  if (!attachment) return null;
78	  const partner = attachment.partner;
79	  if (partner.status !== "ACTIVE") return null;
80	
81	  // FUTURE-ONLY attribution: a partner earns only on charges dated at/after the
82	  // customer was attached to them. Attaching an existing customer therefore never
83	  // back-bills their prior invoices (no surprise retroactive liability); it starts
84	  // the lifetime clock from the attachment forward.
85	  if (inv.createdAt < attachment.createdAt) return null;
86	
87	  const rate = Number.isFinite(partner.commissionRatePct) ? partner.commissionRatePct : 0;
88	  if (rate <= 0) return null;
89	
90	  const baseCents = Math.max(0, inv.amountCents - (inv.taxCents ?? 0));
91	  if (baseCents <= 0) return null;
92	  const amountCents = Math.round((baseCents * rate) / 100);
93	  if (amountCents <= 0) return null;
94	
95	  try {
96	    const row = await db.partnerCommission.create({
97	      data: {
98	        partnerId: partner.id,
99	        customerId: inv.userId,
100	        invoiceId: inv.id,
101	        baseCents,
102	        ratePct: rate,
103	        amountCents,
104	        kind: inferKind(inv.description),
105	        status: "ACCRUED",
106	      },
107	      select: { id: true, amountCents: true },
108	    });
109	    return { commissionId: row.id, amountCents: row.amountCents };
110	  } catch (e) {
111	    // Unique violation on invoiceId => another path already accrued this charge.
112	    // That is the idempotency guarantee working, not an error.
113	    if ((e as Prisma.PrismaClientKnownRequestError)?.code === "P2002") return null;
114	    throw e;
115	  }
116	}
117	
118	/**
119	 * Immediate, best-effort accrual for a customer's most recent qualifying charges.
120	 * Called inline right after a synchronous order/renewal commits so the partner
121	 * sees the commission attach at once (the sweep would otherwise catch it within a
122	 * few minutes). Scans the customer's newest PAID invoices, accruing any that lack
123	 * a commission row. Never throws — logs and moves on.
124	 */
125	export async function accrueRecentCommissionsForCustomer(
126	  customerId: string,
127	  limit = 5
128	): Promise<void> {
129	  try {
130	    // Fast exit for the overwhelmingly common case: the customer has no partner.
131	    const attached = await db.partnerCustomer.findUnique({
132	      where: { customerId },
133	      select: { id: true },
134	    });
135	    if (!attached) return;
136	
137	    const invoices = await db.invoice.findMany({
138	      where: { userId: customerId, status: "PAID", partnerCommission: null },
139	      orderBy: { createdAt: "desc" },
140	      take: limit,
141	      select: { id: true, userId: true, status: true, amountCents: true, taxCents: true, description: true, createdAt: true },
142	    });
143	    for (const inv of invoices) {
144	      await accrueCommissionForInvoice(inv);
145	    }
146	  } catch (e) {
147	    console.error("[partner-commission] inline accrual failed for", customerId, e);
148	  }
149	}
150	
151	/**
152	 * Background reconciliation sweep: accrue commission for every qualifying PAID
153	 * invoice that doesn't yet have a commission row and whose owner is attached to a
154	 * partner. This is the DURABLE hook — it covers every charge path uniformly
155	 * (initial orders, all renewals, upgrades, add-ons, domain/email/hosting/nxcloud
156	 * renewals) without each charge site needing to know about the partner program,
157	 * and it self-heals any charge the inline hooks missed. Idempotent.
158	 *
159	 * Wired into the billing worker loop (worker/index.ts) alongside billingSweep.
160	 * `sinceDays` bounds the scan so it stays cheap on each pass; anything older than
161	 * that has long since been accrued on a prior sweep.
162	 */
163	export async function reconcilePartnerCommissions(
164	  opts: { sinceDays?: number; limit?: number } = {}
165	): Promise<{ scanned: number; accrued: number }> {
166	  const sinceDays = opts.sinceDays ?? 45;
167	  const limit = opts.limit ?? 500;
168	  const since = new Date(Date.now() - sinceDays * 24 * 60 * 60_000);
169	
170	  // Only invoices belonging to an attached customer are candidates. We join through
171	  // PartnerCustomer so partner-less customers (the vast majority) are never scanned.
172	  const invoices = await db.invoice.findMany({
173	    where: {
174	      status: "PAID",
175	      partnerCommission: null,
176	      createdAt: { gte: since },
177	      user: { partnerAttachment: { isNot: null } },
178	    },
179	    orderBy: { createdAt: "asc" },
180	    take: limit,
181	    select: { id: true, userId: true, status: true, amountCents: true, taxCents: true, description: true, createdAt: true },
182	  });
183	
184	  let accrued = 0;
185	  for (const inv of invoices) {
186	    try {
187	      const res = await accrueCommissionForInvoice(inv);
188	      if (res) accrued++;
189	    } catch (e) {
190	      // One bad invoice must never abort the sweep.
191	      console.error("[partner-commission] sweep accrual failed for invoice", inv.id, e);
192	    }
193	  }
194	  return { scanned: invoices.length, accrued };
195	}
196	
197	// ---------- Partner-facing summary ----------
198	
199	export type PartnerSummary = {
200	  partnerId: string;
201	  name: string;
202	  code: string;
203	  commissionRatePct: number;
204	  status: string;
205	  customerCount: number;
206	  /** Lifetime commission ever accrued (ACCRUED + PAID), in cents. */
207	  lifetimeCents: number;
208	  /** Accrued but not yet paid out, in cents. */
209	  outstandingCents: number;
210	  /** Already paid out, in cents. */
211	  paidCents: number;
212	};
213	
214	/**
215	 * Roll up a partner's standing: attached-customer count and commission totals by
216	 * status. Used by both the partner portal and the admin views.
217	 */
218	export async function computePartnerSummary(partnerId: string): Promise<PartnerSummary | null> {
219	  const partner = await db.referralPartner.findUnique({ where: { id: partnerId } });
220	  if (!partner) return null;
221	
222	  const [customerCount, accruedAgg, paidAgg] = await Promise.all([
223	    db.partnerCustomer.count({ where: { partnerId } }),
224	    db.partnerCommission.aggregate({
225	      where: { partnerId, status: "ACCRUED" },
226	      _sum: { amountCents: true },
227	    }),
228	    db.partnerCommission.aggregate({
229	      where: { partnerId, status: "PAID" },
230	      _sum: { amountCents: true },
231	    }),
232	  ]);
233	
234	  const outstandingCents = accruedAgg._sum.amountCents ?? 0;
235	  const paidCents = paidAgg._sum.amountCents ?? 0;
236	  return {
237	    partnerId: partner.id,
238	    name: partner.name,
239	    code: partner.code,
240	    commissionRatePct: partner.commissionRatePct,
241	    status: partner.status,
242	    customerCount,
243	    lifetimeCents: outstandingCents + paidCents,
244	    outstandingCents,
245	    paidCents,
246	  };
247	}
248	
249	/**
250	 * Attach a customer to the partner whose `code` matches, for life. No-op if the
251	 * code doesn't map to an ACTIVE partner, or the customer is already attached to a
252	 * partner (attachment is permanent and single — the unique `customerId` also hard-
253	 * enforces this). Best-effort: returns whether an attachment was made. Intended to
254	 * be called from the registration flow when a `?ref=` code is a partner code.
255	 */
256	export async function attachCustomerToPartnerByCode(
257	  customerId: string,
258	  rawCode: string | null | undefined
259	): Promise<boolean> {
260	  // Partner codes are stored upper-cased (see lib/actions-partner.ts normalizeCode).
261	  const code = (rawCode ?? "").trim().toUpperCase();
262	  if (!code) return false;
263	  try {
264	    const partner = await db.referralPartner.findUnique({ where: { code } });
265	    if (!partner || partner.status !== "ACTIVE") return false;
266	    // A partner cannot self-attach (would earn commission on their own spend).
267	    if (partner.userId && partner.userId === customerId) return false;
268	    const existing = await db.partnerCustomer.findUnique({ where: { customerId } });
269	    if (existing) return false;
270	    await db.partnerCustomer.create({ data: { partnerId: partner.id, customerId } });
271	    return true;
272	  } catch (e) {
273	    // Unique race (two concurrent attaches) or transient error — never fatal to
274	    // the caller (registration/order must still succeed).
275	    if ((e as Prisma.PrismaClientKnownRequestError)?.code === "P2002") return false;
276	    console.error("[partner-commission] attach-by-code failed for", customerId, e);
277	    return false;
278	  }
279	}
