1	"use server";
2	
3	// Admin server actions for the KOL / Agency partner program: create & manage
4	// partners and their commission rates, attach/detach customers, and settle
5	// accrued commission (mark PAID). Billing-area gated, mirroring the existing
6	// affiliate admin actions in lib/actions-affiliate.ts.
7	
8	import { revalidatePath } from "next/cache";
9	import { db } from "./db";
10	import { requireArea } from "./rbac";
11	
12	/** Normalise a partner code: uppercase, alphanumerics/dash, trimmed. */
13	function normalizeCode(raw: string): string {
14	  return raw
15	    .trim()
16	    .toUpperCase()
17	    .replace(/[^A-Z0-9-]/g, "")
18	    .slice(0, 32);
19	}
20	
21	/** Clamp a percent to a sane 0–90 range (integer-ish, 2dp). */
22	function clampRate(raw: number): number {
23	  if (!Number.isFinite(raw)) return 0;
24	  return Math.min(90, Math.max(0, Math.round(raw * 100) / 100));
25	}
26	
27	// ---------- Create a partner ----------
28	
29	export async function adminCreatePartner(
30	  _prev: unknown,
31	  formData: FormData
32	): Promise<{ error?: string; ok?: boolean }> {
33	  const admin = await requireArea("billing");
34	
35	  const name = String(formData.get("name") ?? "").trim();
36	  const code = normalizeCode(String(formData.get("code") ?? ""));
37	  const contactEmail = String(formData.get("contactEmail") ?? "").trim() || null;
38	  const rate = clampRate(Number(formData.get("commissionRatePct")));
39	
40	  if (!name) return { error: "Partner name is required." };
41	  if (code.length < 3) return { error: "Code must be at least 3 characters (A–Z, 0–9, dash)." };
42	  if (rate <= 0) return { error: "Commission rate must be greater than 0%." };
43	
44	  const clash = await db.referralPartner.findUnique({ where: { code } });
45	  if (clash) return { error: "That code is already in use." };
46	
47	  // Optional: link the partner to an existing user account (by email) so they can
48	  // sign in and see their portal. Silently skipped if no such user.
49	  const linkEmail = String(formData.get("linkEmail") ?? "").trim().toLowerCase();
50	  let userId: string | null = null;
51	  if (linkEmail) {
52	    const u = await db.user.findUnique({ where: { email: linkEmail }, select: { id: true } });
53	    if (!u) return { error: `No user account found for ${linkEmail}.` };
54	    const taken = await db.referralPartner.findUnique({ where: { userId: u.id } });
55	    if (taken) return { error: "That user is already a partner." };
56	    userId = u.id;
57	  }
58	
59	  const partner = await db.referralPartner.create({
60	    data: { name, code, contactEmail, commissionRatePct: rate, userId, status: "ACTIVE" },
61	  });
62	  await db.auditLog.create({
63	    data: {
64	      userId: admin.id,
65	      action: "partner.create",
66	      detail: `${partner.name} (${partner.code}) @ ${rate}%`,
67	    },
68	  });
69	  revalidatePath("/admin/partners");
70	  return { ok: true };
71	}
72	
73	// ---------- Update rate / status ----------
74	
75	export async function adminUpdatePartner(
76	  id: string,
77	  patch: { commissionRatePct?: number; status?: string }
78	): Promise<{ error?: string; ok?: boolean }> {
79	  const admin = await requireArea("billing");
80	  const partner = await db.referralPartner.findUnique({ where: { id } });
81	  if (!partner) return { error: "Partner not found." };
82	
83	  const data: { commissionRatePct?: number; status?: string } = {};
84	  if (patch.commissionRatePct != null) {
85	    const rate = clampRate(patch.commissionRatePct);
86	    if (rate <= 0) return { error: "Commission rate must be greater than 0%." };
87	    data.commissionRatePct = rate;
88	  }
89	  if (patch.status != null) {
90	    if (patch.status !== "ACTIVE" && patch.status !== "PAUSED") {
91	      return { error: "Invalid status." };
92	    }
93	    data.status = patch.status;
94	  }
95	  if (Object.keys(data).length === 0) return { error: "Nothing to update." };
96	
97	  await db.referralPartner.update({ where: { id }, data });
98	  await db.auditLog.create({
99	    data: {
100	      userId: admin.id,
101	      action: "partner.update",
102	      detail: `${partner.code} ${JSON.stringify(data)}`,
103	    },
104	  });
105	  revalidatePath("/admin/partners");
106	  revalidatePath(`/admin/partners/${id}`);
107	  return { ok: true };
108	}
109	
110	// ---------- Attach / detach a customer ----------
111	
112	/**
113	 * Attach a customer (by email) to a partner for life. Enforces the single-partner
114	 * rule (a customer already attached to a partner cannot be moved — the unique
115	 * `customerId` also hard-stops it) so attribution is never silently reassigned.
116	 */
117	export async function adminAttachCustomer(
118	  partnerId: string,
119	  email: string
120	): Promise<{ error?: string; ok?: boolean }> {
121	  const admin = await requireArea("billing");
122	  const partner = await db.referralPartner.findUnique({ where: { id: partnerId } });
123	  if (!partner) return { error: "Partner not found." };
124	
125	  const customer = await db.user.findUnique({
126	    where: { email: email.trim().toLowerCase() },
127	    select: { id: true },
128	  });
129	  if (!customer) return { error: "No customer found with that email." };
130	  if (partner.userId && partner.userId === customer.id) {
131	    return { error: "A partner cannot be attached to their own account." };
132	  }
133	
134	  const existing = await db.partnerCustomer.findUnique({
135	    where: { customerId: customer.id },
136	    include: { partner: { select: { name: true } } },
137	  });
138	  if (existing) {
139	    return existing.partnerId === partnerId
140	      ? { error: "That customer is already attached to this partner." }
141	      : { error: `That customer is already attached to ${existing.partner.name}.` };
142	  }
143	
144	  await db.partnerCustomer.create({ data: { partnerId, customerId: customer.id } });
145	  await db.auditLog.create({
146	    data: { userId: admin.id, action: "partner.attach", detail: `${partner.code} <- ${email}` },
147	  });
148	  revalidatePath(`/admin/partners/${partnerId}`);
149	  return { ok: true };
150	}
151	
152	/**
153	 * Detach a customer from a partner. Historical commission rows are LEFT INTACT
154	 * (they record charges that really happened); only the forward attachment is
155	 * removed, so no new commission accrues for this customer afterwards.
156	 */
157	export async function adminDetachCustomer(
158	  attachmentId: string
159	): Promise<{ error?: string; ok?: boolean }> {
160	  const admin = await requireArea("billing");
161	  const attachment = await db.partnerCustomer.findUnique({ where: { id: attachmentId } });
162	  if (!attachment) return { error: "Attachment not found." };
163	
164	  await db.partnerCustomer.delete({ where: { id: attachmentId } });
165	  await db.auditLog.create({
166	    data: {
167	      userId: admin.id,
168	      action: "partner.detach",
169	      detail: `${attachment.partnerId} -/- ${attachment.customerId}`,
170	    },
171	  });
172	  revalidatePath(`/admin/partners/${attachment.partnerId}`);
173	  return { ok: true };
174	}
175	
176	// ---------- Settle commission (mark accrued -> paid) ----------
177	
178	/**
179	 * Mark all currently-ACCRUED commission for a partner as PAID, stamping `paidAt`.
180	 * This records a settlement OUTSIDE the wallet (partners are typically paid by
181	 * bank transfer / invoice), so unlike the affiliate cash-out it moves no wallet
182	 * balance — it only advances the ledger status. Returns how many rows/cents were
183	 * settled.
184	 */
185	export async function adminSettlePartnerCommission(
186	  partnerId: string
187	): Promise<{ error?: string; ok?: boolean; count?: number; cents?: number }> {
188	  const admin = await requireArea("billing");
189	  const partner = await db.referralPartner.findUnique({ where: { id: partnerId } });
190	  if (!partner) return { error: "Partner not found." };
191	
192	  const agg = await db.partnerCommission.aggregate({
